package net.civeira.phylax.feature.oauth.client.domain.gateway;

import java.util.Optional;

import net.civeira.phylax.feature.oauth.client.domain.ClientDetails;

/**
 * Domain port for loading OAuth client data.
 *
 * Responsibilities: - Load client details for different authentication scenarios. - Validate
 * redirect URIs and client secrets as needed.
 *
 * Design notes: - Implemented by infrastructure adapters. - Keeps persistence details outside
 * domain logic.
 */
public interface ClientStoreGateway {

  /**
   * Loads a client that was already pre-authorized.
   *
   * Used when a client is known from an authorization_code flow. Returns empty when the client is
   * not found.
   *
   * @param tenant tenant identifier
   * @param clientId client identifier
   * @return optional client details
   */
  Optional<ClientDetails> loadPreautorized(String tenant, String clientId);

  /**
   * Loads a client that starts an authorization request, validating its redirect URL.
   *
   * Public clients and confidential web apps alike: the confidential ones authenticate later at the
   * token endpoint ({@code protectedWithSecret}), the public ones must use PKCE
   * ({@code requirePkce}). Returns empty when the client or redirect is invalid.
   *
   * @param tenant tenant identifier
   * @param clientId client identifier
   * @param redirect redirect URI
   * @return optional client details
   */
  Optional<ClientDetails> loadForAuthorization(String tenant, String clientId, String redirect);

  /**
   * Loads a confidential client validating the client secret.
   *
   * Used for token endpoint authentication. Returns empty when the secret is invalid.
   *
   * @param tenant tenant identifier
   * @param clientId client identifier
   * @param clientSecret client secret
   * @return optional client details
   */
  Optional<ClientDetails> loadPrivate(String tenant, String clientId, String clientSecret);

  /**
   * Loads a client allowed to act as public (no secret) by its identifier.
   *
   * Used by the token endpoint when the request carries no client secret.
   *
   * @param tenant tenant identifier
   * @param clientId client identifier
   * @return client details, only for clients that allow public access
   */
  Optional<ClientDetails> loadPublicById(String tenant, String clientId);

  /**
   * Loads a confidential client that authenticates with a signed assertion
   * ({@code private_key_jwt}, task 3.2), before the assertion is verified with its keys.
   *
   * @param tenant tenant identifier
   * @param clientId client identifier
   * @return client details as a confidential client, only when it registered private_key_jwt
   */
  Optional<ClientDetails> loadForAssertion(String tenant, String clientId);
}
